import csv
import re
import math
import json
from collections import defaultdict
from datetime import datetime, timezone
from statistics import median as _median


def parse_amount(s: str) -> float:
    if s is None:
        return float('nan')
    s = s.strip()
    if not s:
        return float('nan')

    negative = False
    if 'CR' in s:
        negative = True
    elif s.startswith('(') and s.endswith(')'):
        negative = True
    elif '-' in s:
        negative = True

    s = s.replace('C1', '').replace('C2', '')

    cleaned = []
    for ch in s:
        if ch.isdigit() or ch in ',.':
            cleaned.append(ch)
    s = ''.join(cleaned)

    if not s:
        return float('nan')

    last_comma = s.rfind(',')
    last_dot = s.rfind('.')

    if last_comma == -1 and last_dot == -1:
        val = float(s)
    elif last_comma == -1:
        after = s[last_dot + 1:]
        if len(after) == 2:
            val = float(s)
        else:
            s = s.replace('.', '')
            val = float(s)
    elif last_dot == -1:
        after = s[last_comma + 1:]
        if len(after) == 2:
            s = s.replace(',', '.')
            val = float(s)
        else:
            s = s.replace(',', '')
            val = float(s)
    else:
        if last_dot > last_comma:
            after = s[last_dot + 1:]
            if len(after) == 2:
                s = s.replace(',', '')
                val = float(s)
            else:
                s = s.replace('.', '')
                s = s.replace(',', '.')
                val = float(s)
        else:
            after = s[last_comma + 1:]
            if len(after) == 2:
                s = s.replace('.', '')
                s = s.replace(',', '.')
                val = float(s)
            else:
                s = s.replace(',', '')
                val = float(s)

    return -val if negative else val


def parse_notes(notes: str):
    items = None
    adj_pct = 0.0
    fee = 0.0
    waive = False

    m = re.search(r'items=(\d+)', notes)
    if m:
        items = int(m.group(1))

    m = re.search(r'adj=([+-]?\d+\.?\d*)%', notes)
    if m:
        adj_pct = float(m.group(1))

    m = re.search(r'fee=([+-]?\d+\.?\d*)', notes)
    if m:
        fee = float(m.group(1))

    if re.search(r'waive=true', notes, re.IGNORECASE):
        waive = True

    return items, adj_pct, fee, waive


def answer() -> list[str]:
    rows = []
    with open('/app/dataset/data.csv', 'r') as f:
        reader = csv.reader(f)
        next(reader)
        for i, row in enumerate(reader):
            if len(row) < 6:
                continue
            record_id = row[0].strip()
            event_time_str = row[1].strip()
            region = row[2].strip()
            channel = row[3].strip().lower()
            amount_str = row[4]
            notes = row[5]

            base_amount = parse_amount(amount_str)
            items, adj_pct, fee, waive = parse_notes(notes)

            if math.isnan(base_amount):
                net = float('nan')
            elif waive:
                net = 0.0
            else:
                net = base_amount * (1.0 + adj_pct / 100.0) + fee

            et = None
            if event_time_str:
                try:
                    et = datetime.fromisoformat(event_time_str.replace('Z', '+00:00'))
                except Exception:
                    et = None

            rows.append({
                'record_id': record_id,
                'event_time': et,
                'region': region,
                'channel': channel,
                'net': net,
                'items': items,
                'file_order': i,
                '_amount_str': amount_str,
            })

    groups = defaultdict(list)
    for r in rows:
        groups[r['record_id']].append(r)

    deduped = []
    for rid, recs in groups.items():
        def sort_key(r):
            et = r['event_time']
            net = r['net']
            has_real = 0 if (net is not None and math.isfinite(net)) else 1
            if et is not None:
                return (0, -et.timestamp(), has_real, r['file_order'])
            else:
                return (1, 0, has_real, r['file_order'])
        recs.sort(key=sort_key)
        deduped.append(recs[0])

    filtered = []
    for r in deduped:
        et = r['event_time']
        if et is None:
            continue
        if not (datetime(2025, 10, 1, 0, 0, 0, tzinfo=et.tzinfo)
                <= et <=
                datetime(2025, 12, 31, 23, 59, 59, tzinfo=et.tzinfo)):
            continue
        if r['channel'].strip() == 'phone':
            continue
        if not math.isfinite(r['net']):
            continue
        filtered.append(r)

    month_groups = defaultdict(list)
    for r in filtered:
        month = r['event_time'].strftime('%Y-%m')
        r['month'] = month
        month_groups[(r['region'], month)].append(r)

    for group in month_groups.values():
        nets = [r['net'] for r in group]
        med = _median(nets)
        mads = [abs(n - med) for n in nets]
        mad = _median(mads)
        for r in group:
            if mad == 0.0:
                r['robust_z'] = 0.0
            else:
                r['robust_z'] = 0.6745 * (r['net'] - med) / mad

    for r in filtered:
        items = r['items']
        items_eff = 1 if items is None else max(items, 1)
        r['items_eff'] = items_eff
        r['anomaly_score'] = abs(r['robust_z']) * math.log1p(items_eff)

    filtered.sort(key=lambda r: (
        -r['anomaly_score'],
        -abs(r['robust_z']),
        -r['event_time'].timestamp(),
        r['record_id'],
    ))

    return [r['record_id'] for r in filtered[:10]]


if __name__ == '__main__':
    result = answer()
    with open('/app/answer.json', 'w') as f:
        json.dump(result, f)
    print(result)

